<script setup lang="ts">
import {tr} from '../composables/i18n'
import {CalendarClock,Plus,Pause,Play,Trash2,Pencil,FolderOpen} from 'lucide-vue-next'
import type {Task} from '../types'
import {api,formatDate,providerName} from '../services/api'
import {action} from '../stores/store'
import {t} from '../composables/i18n'
import {stateLabel} from '../types/states'
defineProps<{tasks:Task[];compact?:boolean}>()
defineEmits<{create:[];edit:[task:Task]}>()
</script>
<template><section class="panel task-panel"><div class="panel-heading"><h3><CalendarClock :size="19"/>{{t.recent}}<span class="count">{{tasks.length}}</span></h3><button class="primary small-button" @click="$emit('create')"><Plus :size="16"/>{{t.newTask}}</button></div><div v-if="!tasks.length" class="empty-state"><span class="empty-icon"><CalendarClock :size="30"/></span><h3>{{t.noTasks}}</h3><p>{{t.emptyHint}}</p><button class="text-button" @click="$emit('create')">{{t.newTask}} <Plus :size="14"/></button></div><div v-else class="table-scroll"><table><thead><tr><th>{{tr("执行时间")}}</th><th>{{tr("任务 / 会话")}}</th><th>Provider</th><th>{{tr("状态")}}</th><th>{{tr("操作")}}</th></tr></thead><tbody><tr v-for="task in tasks" :key="task.id"><td class="time-cell">{{formatDate(task.request.scheduled_at_utc)}}</td><td><strong>{{task.request.title}}</strong><small class="task-project"><FolderOpen :size="12"/>{{task.request.conversation.cwd}}</small><small v-if="task.message" class="failure-message">{{task.message}}</small></td><td><span class="provider-label" :class="task.request.conversation.provider">{{providerName(task.request.conversation.provider)}}</span></td><td><span class="badge" :class="task.state">{{stateLabel(task.state)}}</span></td><td><div class="table-actions"><button v-if="task.state==='scheduled'" class="icon-button" :title="tr('立即执行：会发送 AI 请求')" @click="action(()=>api.run(task.id),tr('执行器已启动，请在历史中确认最终结果'))"><Play :size="15"/></button><button v-if="['scheduled','paused'].includes(task.state)" class="icon-button" :title="task.state==='paused'?tr('恢复'):tr('暂停')" @click="action(()=>api.pause(task.id,task.state!=='paused'))"><Play v-if="task.state==='paused'" :size="15"/><Pause v-else :size="15"/></button><button v-if="!['claimed','running','succeeded','cancelled','cancelling'].includes(task.state)" class="icon-button" :title="tr('编辑 / 审查后重排程')" @click="$emit('edit',task)"><Pencil :size="15"/></button><button v-if="task.state!=='cancelled'" class="icon-button" :title="tr('取消 / 停止任务')" @click="action(()=>api.cancel(task.id))"><Trash2 :size="15"/></button></div></td></tr></tbody></table></div></section></template>
